/** 动作键集合：`ui_action` 用它挡住拼错的键 —— 页面收到不认识的键是**静默不动**的，
 *  不挡就等于让 agent 以为按了、其实什么也没发生。 */
export const UI_ACTION_IDS: ReadonlySet<string> = new Set(UI_ACTIONS.map(a => a.action));
